theorem continuous_test_product {s : Set ℝ} (hs : IsOpen s) {b f : ℝ → ℝ}
    (hb : Continuous b) (hf : ContinuousOn f s) (hbs : tsupport b ⊆ s) :
    Continuous (fun t => b t * f t)

theorem radialSupport_fderiv_apply {a b : ℝ} {g : ℝ × E → F}
    (hg : RadiallySupported a b g) (w : ℝ × E) :
    RadiallySupported a b (fun z => fderiv ℝ g z w)

theorem radialSupport_directionalDeriv {a b : ℝ} {g : ℝ × E → F}
    (hg : RadiallySupported a b g) (v : E) :
    RadiallySupported a b (directionalDeriv v g)

theorem aliasIntegral_eq_wholeAlias {a b M : ℝ} {v Y : E} {g : ℝ × E → F}
    (hc : Continuous g) (hs : RadiallySupported a b g) :
    aliasIntegral a b M v Y g = wholeAlias M v Y g

theorem integratingFactor_hasDerivAt (c : ℕ) {W g : ℝ → E} {r : ℝ}
    (hr : r ≠ 0) (hW : HasDerivAt W (g r - ((c : ℝ) / r) • W r) r) :
    HasDerivAt (fun s => s ^ c • W s) (r ^ c • g r) r

theorem continuousOn_pathFamily {U : Set P} {F : P × ℝ → E}
    (hF : ContinuousOn F (U ×ˢ Icc a b)) :
    ContinuousOn (pathFamily (a := a) (b := b) F) U

theorem hasDerivWithinAt_norm_of_ne_zero {u : ℝ → H} {u' : H} {s : Set ℝ} {t : ℝ}
    (hu : HasDerivWithinAt u u' s t) (hne : u t ≠ 0) :
    HasDerivWithinAt (fun x => ‖u x‖) (⟪u t, u'⟫_ℝ / ‖u t‖) s t
